import{_ as e,o as a,c as d,a4 as r}from"./chunks/framework.B6zrJok8.js";const p=JSON.parse('{"title":"Wireframe Format","description":"","frontmatter":{"title":"Wireframe Format"},"headers":[],"relativePath":"excel/wireframe-format.md","filePath":"excel/wireframe-format.md","lastUpdated":null}'),o={name:"excel/wireframe-format.md"};function n(s,t,i,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="wireframe-format" tabindex="-1">Wireframe format <a class="header-anchor" href="#wireframe-format" aria-label="Permalink to &quot;Wireframe format&quot;">​</a></h1><p>This page defines the wireframe format the CLI expects. Use it when preparing or editing the Excel file.</p><h2 id="supported-excel-formats" tabindex="-1">Supported Excel formats <a class="header-anchor" href="#supported-excel-formats" aria-label="Permalink to &quot;Supported Excel formats&quot;">​</a></h2><p>The system auto-detects the format based on column headers:</p><table tabindex="0"><thead><tr><th>Format</th><th>When to use</th><th>Detection</th></tr></thead><tbody><tr><td><strong>CONVERTED</strong></td><td>Standard (recommended)</td><td>Has REFRESH_NAME, REFRESH_DATE, ACTION, ASSET_TYPE, SITE_LOCATION</td></tr><tr><td><strong>BANNER</strong></td><td>Legacy LOFT format</td><td>Has WEB_PROD_CODED, DEVICE with date patterns</td></tr><tr><td><strong>FLAT_TIMED</strong></td><td>Timed refreshes</td><td>Has REFRESH_DATE, START_DATETIME, ACTION</td></tr></tbody></table><h2 id="converted-format-recommended" tabindex="-1">CONVERTED format (recommended) <a class="header-anchor" href="#converted-format-recommended" aria-label="Permalink to &quot;CONVERTED format (recommended)&quot;">​</a></h2><h3 id="required-columns" tabindex="-1">Required columns <a class="header-anchor" href="#required-columns" aria-label="Permalink to &quot;Required columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>REFRESH NAME</code></td><td>Name of the refresh</td><td>&quot;1/26 Winter Sale&quot;</td></tr><tr><td><code>DATE</code> or <code>REFRESH DATE</code></td><td>When content goes live</td><td>1/26/2026</td></tr><tr><td><code>ACTION</code></td><td>What to do</td><td>LAUNCH, NO_CHANGE, REMOVE</td></tr><tr><td><code>SITE LOCATION</code></td><td>Where on site</td><td>HOMEPAGE, PPH, POPUP</td></tr><tr><td><code>ASSET TYPE</code></td><td>Content type</td><td>HOMEPAGE, PPH, COUPONS</td></tr></tbody></table><h3 id="optional-columns" tabindex="-1">Optional columns <a class="header-anchor" href="#optional-columns" aria-label="Permalink to &quot;Optional columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Aliases</th><th>Description</th></tr></thead><tbody><tr><td><code>ZONE</code></td><td>PLACEMENT, PLACEMENT ZONE</td><td>Zone within asset type</td></tr><tr><td><code>COPY</code></td><td>MESSAGE, COPY_MESSAGE, DISCLAIMER</td><td>Marketing copy text</td></tr><tr><td><code>DESTINATION ID</code></td><td>—</td><td>Link destination (category ID or URL)</td></tr><tr><td><code>IPID</code></td><td>—</td><td>Analytics tracking ID</td></tr><tr><td><code>ALT TEXT</code></td><td>—</td><td>Image accessibility text</td></tr><tr><td><code>TIME</code></td><td>START_TIME, TIME (ET)</td><td>Refresh time</td></tr><tr><td><code>ORDER</code></td><td>ITEM #, ITEM_ORDER</td><td>Item order within zone</td></tr><tr><td><code>NOTES</code></td><td>—</td><td>Internal notes</td></tr></tbody></table><h3 id="column-name-aliases" tabindex="-1">Column name aliases <a class="header-anchor" href="#column-name-aliases" aria-label="Permalink to &quot;Column name aliases&quot;">​</a></h3><table tabindex="0"><thead><tr><th>You can use</th><th>Recognized as</th></tr></thead><tbody><tr><td>REFRESH NAME, PROJECT SUMMARY, INITIATIVE</td><td>REFRESH_NAME</td></tr><tr><td>DATE, REFRESH DATE, REFRESH_DATE</td><td>REFRESH_DATE</td></tr><tr><td>ACTION, LAUNCH/REMOVE</td><td>ACTION</td></tr><tr><td>COPY, MESSAGE, PLACEMENT NOTES/PPH MESSAGE</td><td>COPY_MESSAGE</td></tr><tr><td>ZONE, PLACEMENT, PLACEMENT ZONE</td><td>ZONE</td></tr><tr><td>LINK/TRACKING, LINK, TRACKING</td><td>Link (parsed for destination)</td></tr></tbody></table><h2 id="sheet-structure-parent-child-rows" tabindex="-1">Sheet structure: parent-child rows <a class="header-anchor" href="#sheet-structure-parent-child-rows" aria-label="Permalink to &quot;Sheet structure: parent-child rows&quot;">​</a></h2><ul><li><strong>Parent row:</strong> Has REFRESH NAME and DATE; no ASSET TYPE.</li><li><strong>Child rows:</strong> Have ACTION, ASSET TYPE, ZONE; they inherit date from the parent.</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REFRESH NAME     │ DATE      │ ACTION │ ASSET TYPE │ ZONE</span></span>
<span class="line"><span>1/26 Winter Sale │ 1/26/2026 │        │            │        ← Parent</span></span>
<span class="line"><span>                 │           │ LAUNCH │ HOMEPAGE   │ HP_HERO  ← Child</span></span>
<span class="line"><span>                 │           │ LAUNCH │ HOMEPAGE   │ HP_2T    ← Child</span></span>
<span class="line"><span>                 │           │ NO_CHANGE │ PPH     │ PPH      ← Child</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="action-types" tabindex="-1">Action types <a class="header-anchor" href="#action-types" aria-label="Permalink to &quot;Action types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Meaning</th><th>System behavior</th></tr></thead><tbody><tr><td><strong>LAUNCH</strong></td><td>New content</td><td>Generates new HTML, registers in asset registry</td></tr><tr><td><strong>NO_CHANGE</strong></td><td>Same as before</td><td>Reuses asset from registry, no new files</td></tr><tr><td><strong>REMOVE</strong></td><td>Delete content</td><td>Clears the slot</td></tr><tr><td><strong>UPDATE</strong></td><td>Data change only</td><td>Updates JSON, preserves existing HTML</td></tr></tbody></table><h2 id="example-one-row-→-one-asset" tabindex="-1">Example: one row → one asset <a class="header-anchor" href="#example-one-row-→-one-asset" aria-label="Permalink to &quot;Example: one row → one asset&quot;">​</a></h2><p>A single child row with <code>ACTION=LAUNCH</code>, <code>ASSET_TYPE=PPH</code>, <code>ZONE=PPH</code>, <code>COPY=50% off winter</code> becomes one content asset in the refresh JSON under <code>assetsByType.PPH</code>. After build, it appears in the PPH template output and in the OCAPI payload for that slot.</p><h2 id="example-rows-→-json-structure" tabindex="-1">Example: rows → JSON structure <a class="header-anchor" href="#example-rows-→-json-structure" aria-label="Permalink to &quot;Example: rows → JSON structure&quot;">​</a></h2><p>Here are two sample Excel rows (child rows under a parent with REFRESH NAME and DATE) and the shape of the parsed refresh JSON they produce.</p><p><strong>Excel rows (CONVERTED format):</strong></p><table tabindex="0"><thead><tr><th>REFRESH NAME</th><th>DATE</th><th>ACTION</th><th>ASSET TYPE</th><th>ZONE</th><th>COPY</th><th>DESTINATION ID</th></tr></thead><tbody><tr><td>1/26 Winter Sale</td><td>1/26/2026</td><td>LAUNCH</td><td>HOMEPAGE</td><td>HP_HERO</td><td>50% off winter</td><td>/sale/winter</td></tr><tr><td>1/26 Winter Sale</td><td>1/26/2026</td><td>LAUNCH</td><td>PPH</td><td>PPH</td><td>Free shipping</td><td>/shipping</td></tr></tbody></table><p><strong>Resulting structure in <code>refresh.json</code> (simplified):</strong></p><ul><li><code>campaign.refresh.date</code> = <code>&quot;2026-01-26&quot;</code>, <code>campaign.refresh.name</code> = from parent row.</li><li><code>assetsByType.HOMEPAGE.zones</code> = one zone object with <code>zone: &quot;HP_HERO&quot;</code>, <code>items: [{ action: &quot;LAUNCH&quot;, copy: &quot;50% off winter&quot;, destination: &quot;/sale/winter&quot;, ... }]</code>.</li><li><code>assetsByType.PPH.zones</code> = one zone with <code>zone: &quot;PPH&quot;</code>, <code>items: [{ action: &quot;LAUNCH&quot;, copy: &quot;Free shipping&quot;, destination: &quot;/shipping&quot;, ... }]</code>.</li></ul><p>After <strong>make build</strong>, each zone gets rendered HTML and an asset ID (and IPID for LAUNCH). The OCAPI payload then includes these assets and their slot bindings.</p><h2 id="site-locations-and-zones" tabindex="-1">Site locations and zones <a class="header-anchor" href="#site-locations-and-zones" aria-label="Permalink to &quot;Site locations and zones&quot;">​</a></h2><p>Asset types (HOMEPAGE, PPH, POPUP, COUPONS, PLP_HEADER, etc.) and their zones are defined in config. Homepage zones (e.g. HP_TOP_BANNER, HP_2T) are often auto-merged from Excel names like &quot;TOP BANNER&quot; or &quot;SLOT 1&quot;. See <a href="/concepts/slots-assets-zones.html">Slots, Assets, Zones</a> and <a href="/concepts/asset-types-guide.html">Asset Types (data flow)</a>.</p><h2 id="validation-checklist" tabindex="-1">Validation checklist <a class="header-anchor" href="#validation-checklist" aria-label="Permalink to &quot;Validation checklist&quot;">​</a></h2><p>Before saving your wireframe:</p><ul><li>[ ] All required columns present (REFRESH NAME, DATE, ACTION, ASSET TYPE, SITE LOCATION)</li><li>[ ] Actions are valid (LAUNCH, NO_CHANGE, REMOVE, UPDATE)</li><li>[ ] Dates in a format Excel parses (e.g. M/D/YYYY)</li><li>[ ] No empty rows breaking parent-child grouping</li><li>[ ] IPIDs follow naming convention (see <a href="./validation-and-fixes.html">Validation and fixes</a>)</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./how-changeouts-flow.html">How changeouts flow</a> — Commands to run</li><li><a href="./validation-and-fixes.html">Validation and fixes</a> — Errors and how to fix in Excel</li><li><a href="/guides/wireframe.html">Wireframe Guide</a> — Full wireframe reference (IPID format, destination types, multiple sheets)</li></ul>`,33)])])}const m=e(o,[["render",n]]);export{p as __pageData,m as default};
